def sha(path):
    value = hashlib.sha256()
    with Path(path).open('rb') as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b''):
            value.update(block)
    return value.hexdigest()


def canonical(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(',', ':'),
                                     allow_nan=False).encode()).hexdigest()


def read_small(path):
    path = Path(path)
    if path.is_symlink() or not path.is_file() or path.stat().st_size > 16 * 1024 * 1024:
        raise ValueError('Expected a bounded regular JSON file: ' + str(path))
    return json.loads(path.read_text(encoding='utf-8'))


def safe_relative(name):
    if (not isinstance(name, str) or not name or '\\' in name or ':' in name
            or PurePosixPath(name).is_absolute() or any(p in {'', '.', '..'} for p in name.split('/'))):
        raise ValueError('Unsafe relative source path: ' + repr(name))
    return name


def valid_hash(value):
    return isinstance(value, str) and re.fullmatch(r'[0-9a-f]{64}', value) is not None


def checked_map(value, label):
    if not isinstance(value, dict) or not value:
        raise ValueError('Missing ' + label)
    for name, digest in value.items():
        safe_relative(name)
        if not valid_hash(digest):
            raise ValueError('Invalid digest in ' + label)
    return value


def verified_files(root, files, *, results_root=None):
    root = Path(root).resolve(strict=True)
    for name, digest in files.items():
        path = root / safe_relative(name)
        allowed = Path(results_root).resolve(strict=True) if results_root is not None and name.startswith('results/') else root
        if (path.is_symlink() or not path.is_file() or not path.resolve(strict=True).is_relative_to(allowed)
                or sha(path) != digest):
            raise ValueError('Bound source/evidence changed: ' + str(path))
    return canonical(files)


def load_module(path, name):
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    sys.modules[name] = module
    spec.loader.exec_module(module)
    return module


def require_original28(review):
    """Check only original28 declared files, statuses and report bindings."""
    files = checked_map(review.get('original28_files_sha256'), 'original28 evidence')
    matrix = 'results/reliability_v4_humble28_probe_seed004_matrix/'
    required = {'results/freeze_validation/source_freeze_manifest.json', matrix + 'plan.json',
                'config/px4_magnetic_runtime.json'}
    ids = [cls + '_' + group + '_seed004' for cls in ('person', 'car') for group in CORE_GROUPS]
    for trial_id in ids:
        required.update({matrix + 'slots/' + trial_id + suffix for suffix in ('.json', '.started.json')})
    if not required <= set(files):
        raise ValueError('Incomplete original28 plan, source, markers or terminals')
    previous_results = SOURCE / 'results/frozen_fullplan_v4_humble28'
    if (PREVIOUS_ROOT / 'results').resolve(strict=True) != previous_results.resolve(strict=True):
        raise ValueError('Original28 results symlink changed')
    before = verified_files(PREVIOUS_ROOT, files, results_root=previous_results)
    plan = read_small(PREVIOUS_ROOT / matrix / 'plan.json')
    if (plan.get('mode') != 'PROBE' or plan.get('selected_seeds') != [4]
            or {row.get('id') for row in plan.get('trials', [])} != set(ids)):
        raise ValueError('Original28 complete12 plan changed')
    statuses = {}
    for trial_id in ids:
        record = read_small(PREVIOUS_ROOT / matrix / 'slots' / (trial_id + '.json'))
        status = 'FAIL' if trial_id in ORIGINAL_FAILURES else 'PASS'
        if (record.get('id') != trial_id or record.get('status') != status
                or record.get('record_sha256') != canonical({k: v for k, v in record.items() if k != 'record_sha256'})
                or record.get('plan_sha256') != plan.get('plan_sha256')):
            raise ValueError('Original28 outcome/digest changed: ' + trial_id)
        statuses[trial_id] = status
        for item in record.get('evaluations', []):
            path = Path(item.get('report', ''))
            if not path.is_relative_to(PREVIOUS_ROOT):
                raise ValueError('Original28 report escaped root')
            relative = path.relative_to(PREVIOUS_ROOT).as_posix()
            if files.get(relative) != item.get('report_sha256'):
                raise ValueError('Original28 actual report is absent from retention map')
    return {'files_canonical_sha256': before, 'file_count': len(files),
            'core12_statuses': statuses, 'passed': 8, 'failed': 4,
            'scope': 'ORIGINAL28_ARTIFACT_DIGESTS_ONLY_NO_REEVALUATION'}



