import humble33_original32_retention01 as original32
ORIGINAL32_BASE = EXTERNAL / 'humble33_original32_base_snapshot01.json'
ORIGINAL32_BASE_SHA = '51214f15472a3d1dad5a50afe0c7fd94c5441bc2ba465b2c98cdcb8ffd2ffc07'
REQUIRED_HELPERS.add('humble33_original32_retention01.py')
SOURCE_CHANGED = frozenset((
    'ros2_ws/src/uav_tracking_nodes/uav_tracking_nodes/detector_node.py',
    'tests/test_detector_worker.py', 'planning/reliability-v4-current-state.md'))
SOURCE_ADDED = frozenset((
    'ros2_ws/src/uav_tracking_nodes/uav_tracking_nodes/inference_timing.py',
    'tests/test_inference_timing.py',
    'planning/reliability-v4-humble32-execution-20261030.md',
    'planning/reliability-v4-humble32-timing-failure-20261030.md'))


def require_original32(review):
    expected = {'path': ORIGINAL32_BASE.as_posix(), 'sha256': ORIGINAL32_BASE_SHA}
    if review.get('original32_base_snapshot') != expected or sha(ORIGINAL32_BASE) != ORIGINAL32_BASE_SHA:
        raise ValueError('Original32 closed-base snapshot binding differs')
    return original32.verify_base(original32.read(ORIGINAL32_BASE), original32.ORIGINAL_ROOT,
                                  original32.ORIGINAL_RESULTS, EXTERNAL)


def source_delta(files, classified):
    if sha(ORIGINAL32_BASE) != ORIGINAL32_BASE_SHA:
        raise ValueError('Original32 source baseline changed')
    base = original32.read(ORIGINAL32_BASE)
    previous = base['source_files']
    added = set(files) - set(previous)
    removed = set(previous) - set(files)
    changed = {name for name in set(files) & set(previous) if files[name] != previous[name]}
    if removed or added != SOURCE_ADDED or changed != SOURCE_CHANGED:
        raise ValueError('Only the exact seven reviewed timing/test/documentation source differences are permitted')
    prior = base['classified_source_hashes']
    flight_added = set(classified) - set(prior)
    flight_removed = set(prior) - set(classified)
    flight_changed = {name for name in set(classified) & set(prior) if classified[name] != prior[name]}
    timing = 'ros2_ws/src/uav_tracking_nodes/uav_tracking_nodes/inference_timing.py'
    detector = 'ros2_ws/src/uav_tracking_nodes/uav_tracking_nodes/detector_node.py'
    if flight_added != {timing} or flight_removed or flight_changed != {detector}:
        raise ValueError('Only detector instrumentation plus its timing helper may differ in classified flight source')
    return {'baseline_source_commit': original32.SOURCE_COMMIT,
        'baseline_source_canonical_sha256': original32.SOURCE_SHA,
        'changed': sorted(changed), 'added': sorted(added), 'removed': [],
        'classified_changed': [detector], 'classified_added': [timing],
        'algorithm_or_gate_change_authorized': False,
        'claim_boundary': 'Timing instrumentation, its tests and named documentation only; source review is still necessary and runtime remains untested.'}


def helper_manifest33():
    return {'schema_version': 1, 'scope': 'HUMBLE33_FREEZE_BUILD_ONLY_NO_DIAGNOSTIC_OR_FORMAL_ACCEPTANCE',
        'frozen_root': ROOT.as_posix(), 'files': {name: sha(EXTERNAL / name) for name in sorted(REQUIRED_HELPERS)},
        'publication_helpers': {name: sha(EXTERNAL / name) for name in (
            'publish_humble33_final_source_review01.py','publish_humble33_final_source_review01.sh')},
        'original32_base_snapshot_sha256': ORIGINAL32_BASE_SHA,
        'allowed_source_changed': sorted(SOURCE_CHANGED), 'allowed_source_added': sorted(SOURCE_ADDED),
        'formal_seed_use_authorized': False, 'automatic_next_action': False}


def require_reviewed_helpers33(reviewed):
    if not valid_hash(reviewed) or canonical(helper_manifest33()) != reviewed:
        raise ValueError('Explicit final independently reviewed33 helper manifest SHA required')


def candidate_bytes_policy33(commit, files):
    pairs = {}
    for name in sorted(SOURCE_CHANGED | SOURCE_ADDED):
        actual = (SOURCE / name).read_bytes()
        blob = subprocess.check_output(['git', '-C', str(SOURCE), 'show', commit + ':' + name])
        actual_sha = hashlib.sha256(actual).hexdigest()
        blob_sha = hashlib.sha256(blob).hexdigest()
        if actual != blob or actual_sha != files.get(name):
            raise ValueError('Reviewed timing text actual worktree bytes differ from final Git blob: ' + name)
        pairs[name] = {'actual_worktree_sha256': actual_sha, 'git_blob_sha256': blob_sha,
                       'bytes': len(actual), 'actual_equals_git_blob': True}
    return {'authority': 'PHYSICAL_WORKTREE_BYTES_SHA256_COPIED_WITHOUT_NORMALIZATION',
        'source_commit': commit, 'seven_changed_or_added_text_pairs': pairs,
        'unchanged_files': 'Exact original32 physical byte SHA256, including preexisting CRLF assets',
        'status_clean_alone_is_byte_identity': False, 'copy_normalizes_line_endings': False}
